create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text not null default '',
  job_title text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.profiles enable row level security;

create policy "Users can read their profile" on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy "Users can insert their profile" on public.profiles for insert to authenticated with check ((select auth.uid()) = id);
create policy "Users can update their profile" on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'display_name', ''))
  on conflict (id) do nothing;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

-- Enable pgvector (Supabase installs it in the extensions schema).
create extension if not exists vector with schema extensions;

-- 384-dim embedding for all-MiniLM-L6-v2. embedded_at marks that Stage 4 has
-- embedded the row (NULL = still queued for embedding).
alter table public.source_items
  add column if not exists embedding extensions.vector(384),
  add column if not exists embedded_at timestamptz;

-- Approximate nearest-neighbour index (cosine).
create index if not exists source_items_embedding_idx
  on public.source_items using hnsw (embedding extensions.vector_cosine_ops);

-- Scored candidate relationships between two included items. Pairs are stored
-- canonically (source_item_id < related_item_id) so each undirected pair appears
-- once. signals records which deterministic signals fired.
create table if not exists public.item_relationships (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  source_item_id uuid not null references public.source_items(id) on delete cascade,
  related_item_id uuid not null references public.source_items(id) on delete cascade,
  semantic_score numeric(6,5) check (semantic_score between -1 and 1),
  deterministic_score numeric(6,5) check (deterministic_score between 0 and 1),
  combined_score numeric(6,5) check (combined_score between 0 and 1),
  signals jsonb not null default '{}',
  created_at timestamptz not null default now(),
  unique (source_item_id, related_item_id)
);

create index if not exists item_relationships_user_id_idx on public.item_relationships(user_id);
create index if not exists item_relationships_source_idx on public.item_relationships(source_item_id);
create index if not exists item_relationships_combined_idx on public.item_relationships(user_id, combined_score desc);

alter table public.item_relationships enable row level security;
create policy "Users manage their item relationships" on public.item_relationships for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

alter table public.projects
  add column if not exists origin text not null default 'user'
    check (origin in ('user', 'ai'));

create index if not exists projects_user_origin_idx
  on public.projects(user_id, origin);

-- Marks when Stage 6 (extract events & actions) processed a linked item.
alter table public.source_items
  add column if not exists extracted_at timestamptz;

create index if not exists source_items_extract_queue_idx
  on public.source_items(user_id)
  where extracted_at is null;

alter table public.user_corrections drop constraint if exists user_corrections_correction_type_check;
alter table public.user_corrections add constraint user_corrections_correction_type_check
  check (correction_type in ('confirm_match', 'reject_match', 'move_project', 'edit_event', 'edit_action', 'edit_project'));

delete from public.project_events;
delete from public.project_actions;
delete from public.item_relationships;
delete from public.project_source_links;
delete from public.projects;
delete from public.source_items;

create index projects_user_id_idx on public.projects(user_id);
create index source_connections_user_id_idx on public.source_connections(user_id);
create index source_items_user_status_idx on public.source_items(user_id, processing_status);
create index source_items_occurred_at_idx on public.source_items(user_id, occurred_at desc);
create index project_source_links_project_id_idx on public.project_source_links(project_id);
create index project_source_links_source_item_id_idx on public.project_source_links(source_item_id);
create index project_events_project_date_idx on public.project_events(project_id, event_date desc);
create index project_actions_project_due_idx on public.project_actions(project_id, due_date);
create index user_corrections_user_id_idx on public.user_corrections(user_id);

alter table public.projects enable row level security;
alter table public.source_connections enable row level security;
alter table public.source_items enable row level security;
alter table public.project_source_links enable row level security;
alter table public.project_events enable row level security;
alter table public.project_actions enable row level security;
alter table public.user_corrections enable row level security;

